CREATE FUNCTION public.import_cliente(p_cliente uuid, p_bundle jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE r jsonb; t uuid; old_t record; BEGIN
IF NOT EXISTS(SELECT 1 FROM clientes WHERE id=p_cliente AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Cliente não encontrado'; END IF;
IF p_bundle ? 'empresa' THEN UPDATE clientes SET nome=COALESCE(p_bundle->'empresa'->>'nome',nome), cnpj=COALESCE(p_bundle->'empresa'->>'cnpj',cnpj), cidade_uf=COALESCE(p_bundle->'empresa'->>'cidade_uf',cidade_uf), vigencia=COALESCE((p_bundle->'empresa'->>'vigencia')::date,vigencia), aprovado_por=COALESCE(p_bundle->'empresa'->>'aprovado_por',aprovado_por), jornada_semanal=COALESCE((p_bundle->'empresa'->>'jornada_semanal')::numeric,jornada_semanal), dia_inicio=COALESCE(p_bundle->'empresa'->>'dia_inicio',dia_inicio), dia_fim=COALESCE(p_bundle->'empresa'->>'dia_fim',dia_fim), hora_entrada=COALESCE(p_bundle->'empresa'->>'hora_entrada',hora_entrada), hora_saida=COALESCE(p_bundle->'empresa'->>'hora_saida',hora_saida), intervalo=COALESCE(p_bundle->'empresa'->>'intervalo',intervalo), sistema_ponto=COALESCE(p_bundle->'empresa'->>'sistema_ponto',sistema_ponto), canal_denuncias=COALESCE(p_bundle->'empresa'->>'canal_denuncias',canal_denuncias), responsavel_apuracao=COALESCE(p_bundle->'empresa'->>'responsavel_apuracao',responsavel_apuracao), prazo_apuracao_dias=COALESCE((p_bundle->'empresa'->>'prazo_apuracao_dias')::int,prazo_apuracao_dias), valor_max_brindes=COALESCE((p_bundle->'empresa'->>'valor_max_brindes')::numeric,valor_max_brindes), mensagem_lideranca=COALESCE(p_bundle->'empresa'->>'mensagem_lideranca',mensagem_lideranca), incluir_notas_consultor=COALESCE((p_bundle->'empresa'->>'incluir_notas_consultor')::boolean,incluir_notas_consultor) WHERE id=p_cliente; END IF;
IF p_bundle ? 'colaboradores' THEN DELETE FROM colaboradores WHERE cliente_id=p_cliente; FOR r IN SELECT value FROM jsonb_array_elements(p_bundle->'colaboradores') LOOP INSERT INTO colaboradores(cliente_id,nome,cargo,departamento,admissao,posto) VALUES(p_cliente,r->>'nome',r->>'cargo',r->>'departamento',NULLIF(r->>'admissao','')::date,r->>'posto'); END LOOP; END IF;
IF p_bundle ? 'postos' THEN DELETE FROM postos WHERE cliente_id=p_cliente; END IF;
IF p_bundle ? 'turnos' THEN
CREATE TEMP TABLE IF NOT EXISTS old_turnos_import(id uuid,nome text,sigla text) ON COMMIT DROP;
INSERT INTO old_turnos_import SELECT id,nome,sigla FROM turnos WHERE cliente_id=p_cliente;
UPDATE postos SET turno_id=NULL WHERE cliente_id=p_cliente;
DELETE FROM turnos WHERE cliente_id=p_cliente;
FOR r IN SELECT value FROM jsonb_array_elements(p_bundle->'turnos') LOOP INSERT INTO turnos(cliente_id,nome,sigla,inicio,fim,intervalo_min) VALUES(p_cliente,r->>'nome',r->>'sigla',r->>'inicio',r->>'fim',(r->>'intervalo_min')::int); END LOOP;
IF NOT (p_bundle ? 'postos') THEN RAISE EXCEPTION 'Ao substituir turnos, inclua a aba Postos para preservar os vínculos da escala' USING HINT='Inclua ambas as abas'; END IF;
END IF;
IF p_bundle ? 'postos' THEN FOR r IN SELECT value FROM jsonb_array_elements(p_bundle->'postos') LOOP SELECT id INTO t FROM turnos WHERE cliente_id=p_cliente AND (lower(unaccent_name(nome))=lower(unaccent_name(r->>'turno')) OR lower(unaccent_name(sigla))=lower(unaccent_name(r->>'turno'))) LIMIT 1; IF t IS NULL THEN RAISE EXCEPTION 'Turno não encontrado: %',r->>'turno'; END IF; INSERT INTO postos(cliente_id,posto,turno_id,pessoas_por_dia,escala,operacao) VALUES(p_cliente,r->>'posto',t,(r->>'pessoas_por_dia')::int,r->>'escala',r->>'operacao'); END LOOP; END IF;
IF p_bundle ? 'cargos' THEN DELETE FROM cargos WHERE cliente_id=p_cliente; FOR r IN SELECT value FROM jsonb_array_elements(p_bundle->'cargos') LOOP INSERT INTO cargos(cliente_id,familia,cargo,nivel,trilha,salario_base,tempo_minimo_meses,requisitos) VALUES(p_cliente,r->>'familia',r->>'cargo',(r->>'nivel')::int,r->>'trilha',(r->>'salario_base')::numeric,(r->>'tempo_minimo_meses')::int,r->>'requisitos'); END LOOP; END IF;
END $$;
CREATE FUNCTION public.unaccent_name(v text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT translate(trim(v),'áàâãäéèêëíìîïóòôõöúùûüçÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ','aaaaaeeeeiiiiooooouuuucAAAAAEEEEIIIIOOOOOUUUUC') $$;
REVOKE ALL ON FUNCTION public.import_cliente(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.import_cliente(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.duplicate_cliente(p_cliente uuid) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE source clientes; new_id uuid; r turnos; new_t uuid; mapping jsonb='{}'; BEGIN
SELECT * INTO source FROM clientes WHERE id=p_cliente AND user_id=auth.uid(); IF source.id IS NULL THEN RAISE EXCEPTION 'Cliente não encontrado'; END IF;
source.id=gen_random_uuid(); source.nome=source.nome||' (cópia)'; source.criado_em=now(); new_id=source.id;
INSERT INTO clientes SELECT (source).*;
INSERT INTO colaboradores(cliente_id,nome,cargo,departamento,admissao,posto) SELECT new_id,nome,cargo,departamento,admissao,posto FROM colaboradores WHERE cliente_id=p_cliente;
DELETE FROM sancoes WHERE cliente_id=new_id; INSERT INTO sancoes(cliente_id,ordem,situacao,medida,recorrencia) SELECT new_id,ordem,situacao,medida,recorrencia FROM sancoes WHERE cliente_id=p_cliente;
UPDATE config_cargos SET steps=c.steps,pct_entre_steps=c.pct_entre_steps FROM config_cargos c WHERE c.cliente_id=p_cliente AND config_cargos.cliente_id=new_id;
FOR r IN SELECT * FROM turnos WHERE cliente_id=p_cliente LOOP INSERT INTO turnos(cliente_id,nome,sigla,inicio,fim,intervalo_min) VALUES(new_id,r.nome,r.sigla,r.inicio,r.fim,r.intervalo_min) RETURNING id INTO new_t; mapping=mapping||jsonb_build_object(r.id::text,new_t::text); END LOOP;
INSERT INTO postos(cliente_id,posto,turno_id,pessoas_por_dia,escala,operacao) SELECT new_id,posto,(mapping->>turno_id::text)::uuid,pessoas_por_dia,escala,operacao FROM postos WHERE cliente_id=p_cliente;
INSERT INTO cargos(cliente_id,familia,cargo,nivel,trilha,salario_base,tempo_minimo_meses,requisitos) SELECT new_id,familia,cargo,nivel,trilha,salario_base,tempo_minimo_meses,requisitos FROM cargos WHERE cliente_id=p_cliente;
RETURN new_id; END $$;
REVOKE ALL ON FUNCTION public.duplicate_cliente(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.duplicate_cliente(uuid) TO authenticated;